public class SetBitCounter {

    public static int countSetBits(int value) {
        int count = 0;
        for (int i = 0; i < 32; i++) {
            if ((value & 1) == 1) {
                count++;
            }
            value = value >>> 1;
        }
        return count;
    }

    public static boolean isPowerOfTwo(int value) {
        return value > 0 && countSetBits(value) == 1;
    }
}
